package com.redream.launcher;

import android.app.*;
import android.os.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import android.text.*;
import android.net.Uri;
import android.content.Intent;
import org.json.*;
import java.net.*;
import java.io.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
    final int BG=Color.rgb(8,9,13), PANEL=Color.rgb(18,19,25), RED=Color.rgb(255,28,55), MUTED=Color.rgb(157,161,175);
    LinearLayout root, body, nav; String nick="Player", selectedVersion="1.20.1"; JSONArray versions=new JSONArray(); ExecutorService pool=Executors.newSingleThreadExecutor();
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable shape(int color,int radius,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);home();loadVersions();}
    TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));return t;}
    LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
    TextView button(String label,Runnable action,boolean primary){TextView t=text(label,14,Color.WHITE,true);t.setGravity(Gravity.CENTER);t.setPadding(dp(14),dp(14),dp(14),dp(14));t.setBackground(shape(primary?RED:PANEL,14,primary?0:Color.rgb(42,43,52)));t.setOnClickListener(v->action.run());return t;}
    void base(String title,String subtitle){root=column();root.setBackgroundColor(BG);setContentView(root);LinearLayout header=column();pad(header,20,18,20,14);TextView logo=text("RED",25,RED,true);logo.append(text("REAM",25,Color.WHITE,true).getText());header.addView(logo);TextView sub=text(subtitle,12,MUTED,false);header.addView(sub);root.addView(header);ScrollView sc=new ScrollView(this);body=column();pad(body,18,8,18,22);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));nav=row();pad(nav,10,8,10,8);nav.setBackgroundColor(Color.rgb(12,13,18));String[] labels={"Главная","Версии","Моды","Скин","Настройки"};for(String s:labels){TextView n=text(s,10,s.equals(title)?RED:MUTED,true);n.setGravity(Gravity.CENTER);nav.addView(n,new LinearLayout.LayoutParams(0,dp(48),1));n.setOnClickListener(v->{switch(s){case "Главная":home();break;case "Версии":versionsPage();break;case "Моды":modsPage();break;case "Скин":skinPage();break;default:settingsPage();}});}root.addView(nav);}
    void card(String heading,String detail){LinearLayout c=column();c.setBackground(shape(PANEL,18,Color.rgb(34,35,44)));pad(c,16,15,16,15);TextView h=text(heading,16,Color.WHITE,true);c.addView(h);TextView d=text(detail,12,MUTED,false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(7);c.addView(d,p);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(12);body.addView(c,cp);}
    void home(){base("Главная","JAVA EDITION • ANDROID");TextView eyebrow=text("ТВОЙ МИР. ТВОИ ПРАВИЛА.",11,RED,true);body.addView(eyebrow);TextView hero=text("Играй по-своему",28,Color.WHITE,true);LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(-1,-2);hp.topMargin=dp(7);body.addView(hero,hp);card("ПРОФИЛЬ  /  "+nick,"Офлайн-профиль • лицензия и Ely.by будут подключены отдельно");card("ВЫБРАННАЯ ВЕРСИЯ","Minecraft Java "+selectedVersion+"\nВыбор версии и загрузка списка доступны в разделе «Версии».");TextView play=button("▶   ПОДГОТОВИТЬ ЗАПУСК",()->new AlertDialog.Builder(this).setTitle("Запуск Minecraft").setMessage("Это начальная сборка интерфейса. Полноценный запуск Java Edition на Android требует отдельного совместимого игрового runtime, LWJGL/рендерера и загрузчика. APK пока не запускает саму игру.").setPositiveButton("Понятно",null).show(),true);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(6);body.addView(play,bp);card("БЫСТРЫЙ ДОСТУП","Версии • моды • модпаки • скины • сенсорное управление");}
    void loadVersions(){pool.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL("https://piston-meta.mojang.com/mc/game/version_manifest_v2.json").openConnection();c.setConnectTimeout(10000);c.setReadTimeout(10000);ByteArrayOutputStream out=new ByteArrayOutputStream();c.getInputStream().transferTo(out);JSONObject j=new JSONObject(out.toString("UTF-8"));versions=j.getJSONArray("versions");}catch(Exception ignored){}});}
    void versionsPage(){base("Версии","RELEASES • SNAPSHOTS • LEGACY");body.addView(text("Выбери версию Minecraft Java",18,Color.WHITE,true));EditText search=new EditText(this);search.setSingleLine(true);search.setHint("Поиск: 1.8.9, 1.20.1, 24w...");search.setTextColor(Color.WHITE);search.setHintTextColor(MUTED);search.setBackground(shape(PANEL,12,0));pad(search,12,5,12,5);body.addView(search);TextView status=text("Загружаю официальный список Mojang…",12,MUTED,false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(12);body.addView(status,sp);LinearLayout list=column();body.addView(list);Runnable refresh=()->{list.removeAllViews();String q=search.getText().toString().toLowerCase();int count=0;for(int i=0;i<versions.length()&&count<80;i++){JSONObject v=versions.optJSONObject(i);if(v==null)continue;String id=v.optString("id"),type=v.optString("type");if(!id.toLowerCase().contains(q))continue;TextView item=button(id+"   •   "+type,()->{selectedVersion=id;home();},id.equals(selectedVersion));LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,-2);ip.bottomMargin=dp(7);list.addView(item,ip);count++;}status.setText(versions.length()+" версий в каталоге Mojang • нажми версию для выбора");};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){refresh.run();}public void afterTextChanged(Editable e){}});refresh.run();}
    void modsPage(){base("Моды","LOCAL FILES • MODPACKS");card("УСТАНОВЛЕННЫЕ МОДЫ","Здесь будут отображаться моды для выбранного профиля и загрузчика.");TextView pick=button("＋   ИМПОРТИРОВАТЬ MOD / MODPACK",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/java-archive","application/zip","application/octet-stream"});i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,22);},true);body.addView(pick);card("ПОДДЕРЖИВАЕМЫЕ ФОРМАТЫ",".jar — моды • .zip — модпаки (импорт интерфейса; установка пока не реализована)");}
    @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==22&&res==RESULT_OK&&data!=null){Uri u=data.getData();new AlertDialog.Builder(this).setTitle("Файл выбран").setMessage(u==null?"Файл не выбран":u.getLastPathSegment()+"\nИмпорт в профиль будет добавлен в следующем этапе.").setPositiveButton("OK",null).show();}}
    void skinPage(){base("Скин","PLAYER • PREVIEW");card("ПРОСМОТР СКИНА","Здесь будет вращаемая 3D-модель персонажа. В этой сборке 3D-рендер ещё не подключён.");body.addView(button("ЗАГРУЗИТЬ PNG-СКИН",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/png");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,23);},true));card("ПРИМЕЧАНИЕ","Офлайн-скин локален. Для отображения скина на серверах требуется серверная поддержка или соответствующая авторизация.");}
    void settingsPage(){base("Настройки","CONTROLS • PERFORMANCE");card("СЕНСОРНОЕ УПРАВЛЕНИЕ","Профили кнопок, масштаб HUD и раскладка будут доступны в игровом экране после интеграции runtime.");card("ПАМЯТЬ И ПРОИЗВОДИТЕЛЬНОСТЬ","Рекомендуется оставить свободными несколько гигабайт памяти. Параметры JVM появятся после реализации запуска.");body.addView(button("ИЗМЕНИТЬ OFFLINE-НИК",()->{EditText e=new EditText(this);e.setSingleLine();e.setText(nick);new AlertDialog.Builder(this).setTitle("Никнейм").setView(e).setNegativeButton("Отмена",null).setPositiveButton("Сохранить",(d,w)->{String n=e.getText().toString().trim();if(n.matches("[A-Za-z0-9_]{3,16}"))nick=n;else Toast.makeText(this,"Ник: 3–16 символов A–Z, 0–9, _",Toast.LENGTH_LONG).show();settingsPage();}).show();},false));}
    @Override protected void onDestroy(){super.onDestroy();pool.shutdownNow();}
}
